import type {
  BlockPlan,
  CoachPlan,
  ReviewKind,
  WeekPlan,
} from "@killingit/shared";
import {
  formatBlockPlan,
  formatPlanContext,
  formatSeasonPlan,
  formatWeekPlan,
  type PlanContextInput,
} from "./planContext.js";
import { COACH_PERSONA, PLAIN_TEXT_RULES } from "./promptRules.js";

/**
 * Bump when the summary prompt or generation parameters change materially.
 * Reviews generated by an older version are ignored and regenerated.
 */
export const PERIOD_REVIEW_PROMPT_VERSION = 1;

export interface PeriodReviewPromptInput {
  today: string;
  kind: ReviewKind;
  plan: CoachPlan;
  startDate: string;
  endDate: string;
  title: string;
  /** The detailed week being reviewed, when `kind` is `week`. */
  week?: WeekPlan;
  /** The detailed block being reviewed, when `kind` is `block`. */
  block?: BlockPlan;
  context: PlanContextInput;
}

const PERIOD_REVIEW_SYSTEM_PROMPT = `${COACH_PERSONA} Summarise a completed training period for the athlete.
Write 3-5 sentences of plain text. Say what the athlete completed and how consistently they trained, how the period fit the overall plan, what worked, and what should change in the next period. Cite only the most useful activity data. Be encouraging when the work was reasonable, but be honest about missed sessions and warning signs. ${PLAIN_TEXT_RULES}`;

/** Builds the messages that ask the coach for a week or block summary. */
export function buildPeriodReviewMessages(input: PeriodReviewPromptInput): {
  role: "system" | "user";
  content: string;
}[] {
  return [
    { role: "system", content: PERIOD_REVIEW_SYSTEM_PROMPT },
    { role: "user", content: buildPeriodReviewPrompt(input) },
  ];
}

/** Exposed for tests and for inspecting exactly what is sent to the model. */
export function buildPeriodReviewPrompt(
  input: PeriodReviewPromptInput,
): string {
  const lines = [
    ...formatPlanContext(input.context),
    "",
    `Completed ${input.kind}: ${input.title} (${input.startDate} → ${input.endDate})`,
  ];

  if (input.kind === "week" && input.week) {
    lines.push("", "Completed week plan:", formatWeekPlan(input.week));
  } else if (input.kind === "block" && input.block) {
    lines.push(
      "",
      "Season plan:",
      formatSeasonPlan(input.plan.season),
      "",
      "Completed block plan:",
      formatBlockPlan(input.block),
    );
  }

  lines.push("", `Write the coach summary for this completed ${input.kind}.`);
  return lines.join("\n");
}
